use tokio::fs;
use tokio::io::AsyncWriteExt;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("=== Async File I/O ===");

    // ---- Writing to a file ----
    let content = "Hello, async world!\nThis is written asynchronously.";
    fs::write("async_output.txt", content).await?;
    println!("✅ File written!");

    // ---- Reading from a file ----
    let data = fs::read_to_string("async_output.txt").await?;
    println!("File contents:\n{}", data);

    // ---- Creating and writing with async file ----
    let mut file = fs::File::create("async_log.txt").await?;
    file.write_all(b"Log entry 1: Started\n").await?;
    file.write_all(b"Log entry 2: Processing\n").await?;
    file.write_all(b"Log entry 3: Complete\n").await?;
    println!("✅ Log file written!");

    // ---- Reading file metadata ----
    let metadata = fs::metadata("async_log.txt").await?;
    println!("Log file size: {} bytes", metadata.len());
    println!("Is file? {}", metadata.is_file());

    // ---- Appending to a file ----
    let mut file = fs::OpenOptions::new()
        .append(true)
        .open("async_log.txt")
        .await?;
    file.write_all(b"Log entry 4: Appended\n").await?;
    println!("✅ Log appended!");

    // ---- Reading all lines ----
    let content = fs::read_to_string("async_log.txt").await?;
    println!("\nFinal log contents:");
    for (i, line) in content.lines().enumerate() {
        println!("  {}: {}", i + 1, line);
    }

    // ---- Checking if file exists ----
    let exists = fs::try_exists("async_output.txt").await?;
    println!("async_output.txt exists: {}", exists);

    // ---- Removing file ----
    fs::remove_file("async_output.txt").await?;
    println!("✅ async_output.txt removed!");

    Ok(())
}

